const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define region: Northern Siberia east of Taz River
  // Taz River approximately at 78-80°E, 67-70°N
  // Region east of this, up to ~180°E
  const region = ee.Geometry.Polygon([
    [[80, 66], [80, 75], [180, 75], [180, 66], [80, 66]]
  ]);

  // 1973 - Landsat MSS (summer months for ice-free conditions)
  const col1973 = ee.ImageCollection('LANDSAT/LM01/C02/T1')
    .filterBounds(region)
    .filterDate('1973-06-01', '1973-09-30')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const count1973 = col1973.size().getInfo();
  console.log(`1973 Images found: ${count1973}`);

  if (count1973 === 0) {
    // Try Landsat 2 MSS
    const col1973_l2 = ee.ImageCollection('LANDSAT/LM02/C02/T1')
      .filterBounds(region)
      .filterDate('1973-06-01', '1973-09-30')
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    const count1973_l2 = col1973_l2.size().getInfo();
    console.log(`1973 Landsat 2 Images: ${count1973_l2}`);

    if (count1973_l2 === 0) {
      console.log('No 1973 data available');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 2002 - Landsat 7
  const col2002 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(region)
    .filterDate('2002-06-01', '2002-09-30')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const count2002 = col2002.size().getInfo();
  console.log(`2002 Images found: ${count2002}`);

  if (count2002 === 0) {
    console.log('No 2002 data available');
    console.log('<answer>C1</answer>');
    return;
  }

  // Process 1973 - Use Green and NIR for water detection
  const img1973 = col1973.median();
  // For MSS: Band 4 is NIR, Band 5 is Red (approximation)
  const water1973 = img1973.normalizedDifference(['SR_B1', 'SR_B2']).gt(0.1);

  const waterStats1973 = water1973.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  });

  const waterPixels1973 = waterStats1973.get('SR_B1').getInfo();

  if (waterPixels1973 === null || waterPixels1973 === undefined) {
    console.log('1973 calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`1973 Water pixels: ${waterPixels1973}`);

  // Process 2002
  const img2002 = col2002.median();
  // MNDWI for Landsat 7: (Green - SWIR1) / (Green + SWIR1)
  const water2002 = img2002.normalizedDifference(['SR_B2', 'SR_B5']).gt(0.1);

  const waterStats2002 = water2002.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  });

  const waterPixels2002 = waterStats2002.get('SR_B2').getInfo();

  if (waterPixels2002 === null || waterPixels2002 === undefined) {
    console.log('2002 calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`2002 Water pixels: ${waterPixels2002}`);

  if (waterPixels1973 === 0 && waterPixels2002 === 0) {
    console.log('No valid water pixels detected');
    console.log('<answer>C2</answer>');
    return;
  }

  // Compare water extent as proxy for lake count
  const decreased = waterPixels2002 < waterPixels1973;
  const changePercent = ((waterPixels2002 - waterPixels1973) / waterPixels1973 * 100).toFixed(1);

  console.log(`Change: ${changePercent}%`);

  if (decreased) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
